 "content": "def transform(grid):
    # Recolor every zero cell in the unique horizontal row of 5 adjacent 5s
    # (the long marker stripe) to 8. Mark the singleton zero as 7.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for r, row in enumerate(grid):
        if len(row) >= 5 and any(all(row[c + k] == 5 for k in range(5)) for c in range(len(row) - 4)):
            for c, value in enumerate(row):
                if value == 0:
                    out[r][c] = 8
    # Observed demos contain a special isolated 0 transformed to 7; infer it as
    # an isolated zero adjacent to the bottom-left border.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not any(
                0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 0
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            ):
                out[r][c] = 7
    return out

